type NaxFormExpose = {
    validate : () => Promise
    resetFields : () => void
    clearValidate : () => void
}
const formRef = ref(null as NaxFormExpose | null)

const name = ref('')
const phone = ref('')
const email = ref('')
const password = ref('')
const intro = ref('')
const sex = ref('')
const agree = ref(false)

// 控件 v-model 与 UTSJSONObject model 双向同步
const formModel = {
    name: '',
    phone: '',
    email: '',
    password: '',
    intro: '',
    sex: '',
    agree: false
} as UTSJSONObject

function syncFormModel() {
    formModel.set('name', name.value)
    formModel.set('phone', phone.value)
    formModel.set('email', email.value)
    formModel.set('password', password.value)
    formModel.set('intro', intro.value)
    formModel.set('sex', sex.value)
    formModel.set('agree', agree.value)
}

const rules = {
    name: [
        {
            required: true,
            message: '请输入姓名',
            trigger: ['blur', 'change']
        } as UTSJSONObject,
        {
            min: 2,
            max: 10,
            message: '姓名长度 2-10 个字'
        } as UTSJSONObject
    ] as any[],
    phone: [
        {
            required: true,
            message: '请输入手机号'
        } as UTSJSONObject,
        {
            pattern: '^1\\d{10}$',
            message: '手机号格式不正确'
        } as UTSJSONObject
    ] as any[],
    email: [
        {
            type: 'email',
            message: '邮箱格式不正确'
        } as UTSJSONObject
    ] as any[],
    password: [
        {
            required: true,
            message: '请输入密码'
        } as UTSJSONObject,
        {
            min: 6,
            max: 20,
            message: '密码 6-20 位'
        } as UTSJSONObject
    ] as any[],
    intro: [
        {
            min: 5,
            message: '简介至少 5 个字'
        } as UTSJSONObject
    ] as any[],
    sex: [
        {
            required: true,
            message: '请选择性别'
        } as UTSJSONObject
    ] as any[],
    agree: [
        {
            type: 'accepted',
            required: true,
            message: '请勾选用户协议'
        } as UTSJSONObject
    ] as any[]
} as UTSJSONObject

function onSubmit() {
    syncFormModel()
    if (formRef.value == null) {
        return
    }
    formRef.value.validate().then((ok: boolean) => {
        // 校验通过
    }).catch((err: any | null) => {
        // 校验失败，字段下方展示错误文案
    })
}

function onReset() {
    name.value = ''
    phone.value = ''
    email.value = ''
    password.value = ''
    intro.value = ''
    sex.value = ''
    agree.value = false
    syncFormModel()
    if (formRef.value != null) {
        formRef.value.resetFields()
        formRef.value.clearValidate()
    }
}

function onClear() {
    if (formRef.value != null) {
        formRef.value.clearValidate()
    }
}

